mapper.select:
SELECT a.FINPROD_ID AS prodId, a.FINPROD_NAME AS prodName, to_char(a.VAL_DATE, 'yyyy-MM-dd') AS valueDate, a.CAPITAL AS financialShare, a.ASSET_VALUE AS totalNetProd, a.NET_UNIT_VALUE AS netUnitProd, a.CHECK_STATUS AS reconcileStatus, a.CHECK_STATUS AS reconcileStatusString, a.CHECK_RESULT AS reconcileResult, a.CHECK_RESULT AS reconcileResultString, '' AS remark, c2.file_path AS filePath2,/**他方对比文件**/ d2.file_path AS filePath3 /**对账结果文件**/ FROM BOK_VALBAL_TABLE_STATUS a LEFT JOIN BOK_VALBAL_TABLE_FILE c ON a.finprod_id = c.finprod_id AND a.val_date = c.val_date AND a.val_bal_flag = c.val_bal_flag AND c.file_type = '05' LEFT JOIN BOK_FILE_INFO c2 ON c.file_id = c2.file_id AND c.File_Type = c2.file_type LEFT JOIN BOK_VALBAL_TABLE_FILE d ON a.finprod_id = d.finprod_id AND a.val_date = d.val_date AND a.val_bal_flag = d.val_bal_flag AND d.file_type = '01' LEFT JOIN BOK_FILE_INFO d2 ON d.file_id = d2.file_id AND d.File_Type = d2.file_type WHERE 1=1 AND a.VAL_BAL_FLAG = '01' AND a.VAL_DATE >= to_date(#{valDateBegin,jdbcType=VARCHAR},'yyyy-MM-dd') AND a.VAL_DATE <= to_date(#{valDateEnd,jdbcType=VARCHAR},'yyyy-MM-dd')
#{item}
AND a.CHECK_STATUS = #{reconcileStatus,jdbcType=VARCHAR} AND a.CHECK_RESULT = #{reconcileResult,jdbcType=VARCHAR} ORDER BY a.VAL_DATE ASC,a.FINPROD_ID
